-- =====================================================================
-- V1 · Initial schema (see docs/data-model.md)
-- IDs are UUID v7 generated by the application (Hibernate).
-- =====================================================================

CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- ---------------------------------------------------------------------
-- customer
-- ---------------------------------------------------------------------
CREATE TABLE customers
(
    id            UUID         NOT NULL,
    first_name    VARCHAR(100) NOT NULL,
    last_name     VARCHAR(100) NOT NULL,
    email         VARCHAR(254) NOT NULL,
    phone         VARCHAR(20)  NOT NULL,
    address       VARCHAR(255) NOT NULL,
    password_hash VARCHAR(100) NOT NULL,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_customers PRIMARY KEY (id),
    CONSTRAINT uq_customers_email UNIQUE (email),
    CONSTRAINT uq_customers_phone UNIQUE (phone)
);

-- ---------------------------------------------------------------------
-- tokenization (card vault) — the CVV is never stored (ADR-005)
-- ---------------------------------------------------------------------
CREATE TABLE cards
(
    id                UUID        NOT NULL,
    token             VARCHAR(40) NOT NULL,
    customer_id       UUID        NOT NULL,
    encrypted_payload BYTEA       NOT NULL,
    iv                BYTEA       NOT NULL,
    key_id            VARCHAR(20) NOT NULL,
    last4             CHAR(4)     NOT NULL,
    brand             VARCHAR(20) NOT NULL,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_cards PRIMARY KEY (id),
    CONSTRAINT uq_cards_token UNIQUE (token),
    CONSTRAINT fk_cards_customer FOREIGN KEY (customer_id) REFERENCES customers (id),
    CONSTRAINT ck_cards_iv_length CHECK (octet_length(iv) = 12)
);
CREATE INDEX ix_cards_customer_id ON cards (customer_id);

-- ---------------------------------------------------------------------
-- product
-- ---------------------------------------------------------------------
CREATE TABLE products
(
    id          UUID           NOT NULL,
    sku         VARCHAR(40)    NOT NULL,
    name        VARCHAR(150)   NOT NULL,
    description TEXT,
    price       NUMERIC(12, 2) NOT NULL,
    stock       INTEGER        NOT NULL,
    version     BIGINT         NOT NULL DEFAULT 0,
    CONSTRAINT pk_products PRIMARY KEY (id),
    CONSTRAINT uq_products_sku UNIQUE (sku),
    CONSTRAINT ck_products_price_positive CHECK (price > 0),
    CONSTRAINT ck_products_stock_non_negative CHECK (stock >= 0)
);
-- Trigram indexes make ILIKE '%term%' searches use an index instead of a full scan
CREATE INDEX ix_products_name_trgm ON products USING gin (name gin_trgm_ops);
CREATE INDEX ix_products_description_trgm ON products USING gin (description gin_trgm_ops);
CREATE INDEX ix_products_stock ON products (stock);

CREATE TABLE search_logs
(
    id             UUID         NOT NULL,
    query          VARCHAR(100),
    results_count  INTEGER      NOT NULL,
    customer_id    UUID,
    transaction_id UUID,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_search_logs PRIMARY KEY (id),
    CONSTRAINT fk_search_logs_customer FOREIGN KEY (customer_id) REFERENCES customers (id)
);
CREATE INDEX ix_search_logs_created_at ON search_logs (created_at);

-- ---------------------------------------------------------------------
-- cart
-- ---------------------------------------------------------------------
CREATE TABLE carts
(
    id          UUID        NOT NULL,
    customer_id UUID        NOT NULL,
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_carts PRIMARY KEY (id),
    CONSTRAINT uq_carts_customer UNIQUE (customer_id),
    CONSTRAINT fk_carts_customer FOREIGN KEY (customer_id) REFERENCES customers (id)
);

CREATE TABLE cart_items
(
    id         UUID    NOT NULL,
    cart_id    UUID    NOT NULL,
    product_id UUID    NOT NULL,
    quantity   INTEGER NOT NULL,
    CONSTRAINT pk_cart_items PRIMARY KEY (id),
    CONSTRAINT uq_cart_items_cart_product UNIQUE (cart_id, product_id),
    CONSTRAINT fk_cart_items_cart FOREIGN KEY (cart_id) REFERENCES carts (id) ON DELETE CASCADE,
    CONSTRAINT fk_cart_items_product FOREIGN KEY (product_id) REFERENCES products (id),
    CONSTRAINT ck_cart_items_quantity_positive CHECK (quantity > 0)
);
CREATE INDEX ix_cart_items_product_id ON cart_items (product_id);

-- ---------------------------------------------------------------------
-- order / payment
-- ---------------------------------------------------------------------
CREATE TABLE orders
(
    id               UUID           NOT NULL,
    customer_id      UUID           NOT NULL,
    card_id          UUID           NOT NULL,
    delivery_address VARCHAR(255)   NOT NULL,
    status           VARCHAR(20)    NOT NULL,
    total            NUMERIC(12, 2) NOT NULL,
    transaction_id   UUID,
    created_at       TIMESTAMPTZ    NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ    NOT NULL DEFAULT now(),
    CONSTRAINT pk_orders PRIMARY KEY (id),
    CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id) REFERENCES customers (id),
    CONSTRAINT fk_orders_card FOREIGN KEY (card_id) REFERENCES cards (id),
    CONSTRAINT ck_orders_status CHECK (status IN ('PENDING_PAYMENT', 'PAID', 'PAYMENT_FAILED')),
    CONSTRAINT ck_orders_total_positive CHECK (total > 0)
);
CREATE INDEX ix_orders_customer_id ON orders (customer_id);
CREATE INDEX ix_orders_card_id ON orders (card_id);

CREATE TABLE order_items
(
    id           UUID           NOT NULL,
    order_id     UUID           NOT NULL,
    product_id   UUID           NOT NULL,
    product_name VARCHAR(150)   NOT NULL,
    unit_price   NUMERIC(12, 2) NOT NULL,
    quantity     INTEGER        NOT NULL,
    CONSTRAINT pk_order_items PRIMARY KEY (id),
    CONSTRAINT fk_order_items_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE,
    CONSTRAINT fk_order_items_product FOREIGN KEY (product_id) REFERENCES products (id),
    CONSTRAINT ck_order_items_quantity_positive CHECK (quantity > 0)
);
CREATE INDEX ix_order_items_order_id ON order_items (order_id);

CREATE TABLE payment_attempts
(
    id             UUID        NOT NULL,
    order_id       UUID        NOT NULL,
    attempt_number INTEGER     NOT NULL,
    result         VARCHAR(20) NOT NULL,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_payment_attempts PRIMARY KEY (id),
    CONSTRAINT uq_payment_attempts_order_attempt UNIQUE (order_id, attempt_number),
    CONSTRAINT fk_payment_attempts_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE,
    CONSTRAINT ck_payment_attempts_result CHECK (result IN ('APPROVED', 'REJECTED'))
);

-- ---------------------------------------------------------------------
-- audit (append-only, intentionally without FKs)
-- ---------------------------------------------------------------------
CREATE TABLE audit_events
(
    id             UUID        NOT NULL,
    transaction_id UUID        NOT NULL,
    event_type     VARCHAR(50) NOT NULL,
    entity_type    VARCHAR(30),
    entity_id      VARCHAR(64),
    outcome        VARCHAR(10) NOT NULL,
    details        JSONB,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_audit_events PRIMARY KEY (id),
    CONSTRAINT ck_audit_events_outcome CHECK (outcome IN ('SUCCESS', 'FAILURE'))
);
CREATE INDEX ix_audit_events_transaction_id ON audit_events (transaction_id);
CREATE INDEX ix_audit_events_entity ON audit_events (entity_type, entity_id);
CREATE INDEX ix_audit_events_created_at ON audit_events (created_at);
